import heapq

def shortest_path(edges, start, end):
    """
    Find the shortest path between two nodes in a directed weighted graph.

    Args:
        edges: List of tuples (from_node, to_node, weight)
        start: Starting node
        end: Ending node

    Returns:
        Tuple (distance, path) where distance is total weight and 
        path is list of nodes along the shortest route

    Raises:
        ValueError: If any edge has a negative weight

    Examples:
        >>> shortest_path([("A","B",1), ("B","C",2), ("A","C",5)], "A", "C")
        (3, ["A", "B", "C"])
    """
    # Handle the case where start and end are the same node
    if start == end:
        return (0, [start])

    # Build adjacency list from edges
    graph = {node: [] for node in set(edge[0] for edge in edges) | 
                     set(edge[1] for edge in edges)}

    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        if to_node not in graph:
            graph[to_node] = []
        graph[from_node].append((to_node, weight))

    # Check for negative weights (raises ValueError if found)
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative weight edge found")

    # If either start or end node is not in the graph at all
    if start not in graph or end not in graph:
        return (None, None)

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    pq = [(0, start)]  # Min-heap with (distance, node)
    came_from = {}  # To reconstruct path

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        # Skip if we've already found a shorter path to this node
        if current_dist > distances[current_node]:
            continue

        # If we've reached the target node, we can stop early
        if current_node == end:
            break

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, []):
            distance = distances[current_node] + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                came_from[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor))

    # Check if end is reachable
    if distances[end] == float('inf'):
        return (None, None)

    # Reconstruct path from end to start
    path = []
    current = end
    while current != start:
        path.append(current)
        if current not in came_from:
            break  # Shouldn't happen if we reached the target
        current = came_from[current]
    path.append(start)

    path.reverse()

    return (distances[end], path)
